  function swap(
    IERC20 fromToken,
    IERC20 toToken,
    uint256 fromAmount,
    uint256 networkFee,
    Utils.Route[] calldata route
  ) external payable override {
    for (uint256 i = 0; i < route.length; i++) {
      if (route[i].index == 1) {
        //swap on 0xV4
        swapOnZeroXv4(
          fromToken,
          toToken,
          fromAmount.mul(route[i].percent).div(10000),
          route[i].targetExchange,
          route[i].payload
