        //swap on 0xV2
        swapOnZeroXv2(
          fromToken,
          toToken,
          fromAmount.mul(route[i].percent).div(10000),
          route[i].targetExchange,
          route[i].payload
        );
      } else if (route[i].index == 3) {
        //swap on curve
        swapOnCurve(
          fromToken,
          toToken,
          fromAmount.mul(route[i].percent).div(10000),
          route[i].targetExchange,
          route[i].payload
        );
      } else if (route[i].index == 4) {
        //swap on uniswapV2Fork
        swapOnUniswapV2Fork(
          fromToken,
          toToken,
          fromAmount.mul(route[i].percent).div(10000),
          route[i].payload
        );
      } else if (route[i].index == 5) {
        //swap on balancer
        swapOnBalancer(
          fromToken,
          toToken,
          fromAmount.mul(route[i].percent).div(10000),
          route[i].targetExchange,
          route[i].payload
        );
      } else if (route[i].index == 6) {
        //swap on uniswapv3
        swapOnUniswapV3(
          fromToken,
          toToken,
          fromAmount.mul(route[i].percent).div(10000),
          route[i].targetExchange,
          route[i].payload
        );
      } else if (route[i].index == 7) {
        //swap on aavee2
        swapOnAaveeV2(
          fromToken,
          toToken,
          fromAmount.mul(route[i].percent).div(10000),
          route[i].payload
        );
      } else if (route[i].index == 8) {
        //swap on oneinch
        swapOnOneInch(
          fromToken,
          toToken,
          fromAmount.mul(route[i].percent).div(10000),
          route[i].targetExchange
        );
      } else if (route[i].index == 9) {
        //swap on Mstable
        swapOnMStable(
          fromToken,
          toToken,
          fromAmount.mul(route[i].percent).div(10000),
          route[i].targetExchange,
          route[i].payload
        );
      } else if (route[i].index == 10) {
