pragma solidity 0.7.5;

interface IMStable {
  function mint(
    address _input,
    uint256 _inputQuantity,
    uint256 _minOutputQuantity,
    address _recipient
  ) external virtual returns (uint256 mintOutput);

  function swap(
    address _input,
    address _output,
