        //swap on curve
        swapOnCurve(
          fromToken,
          toToken,
          fromAmount.mul(route[i].percent).div(10000),
          route[i].targetExchange,
          route[i].payload
        );
      } else if (route[i].index == 4) {
        //swap on uniswapV2Fork
        swapOnUniswapV2Fork(
          fromToken,
          toToken,
          fromAmount.mul(route[i].percent).div(10000),
          route[i].payload
        );
      } else if (route[i].index == 5) {
        //swap on balancer
        swapOnBalancer(
          fromToken,
          toToken,
          fromAmount.mul(route[i].percent).div(10000),
          route[i].targetExchange,
          route[i].payload
        );
      } else if (route[i].index == 6) {
