      );
      Utils.approve(_swap.pool, _fromToken, adjustedInParam);
      IBalancerPool(_swap.pool).swapExactAmountIn(
        _fromToken,
        adjustedInParam,
        _toToken,
        _swap.tokenOutParam,
        _swap.maxPrice
      );
    }

    if (address(toToken) == Utils.ethAddress()) {
      IWETH(WETH).withdraw(IERC20(WETH).balanceOf(address(this)));
    }
