pragma solidity 0.7.5;

contract Curve {
  struct CurveData {
    int128 i;
    int128 j;
    uint256 deadline;
    bool underlyingSwap;
  }

  function swapOnCurve(
    IERC20 fromToken,
    IERC20 toToken,
    uint256 fromAmount,
    address exchange,
    bytes calldata payload
  ) internal {
    CurveData memory curveData = abi.decode(payload, (CurveData));

    Utils.approve(address(exchange), address(fromToken), fromAmount);

    if (curveData.underlyingSwap) {
      ICurvePool(exchange).exchange_underlying(
        curveData.i,
        curveData.j,
        fromAmount,
        1
      );
    } else {
      if (address(fromToken) == Utils.ethAddress()) {
        ICurveEthPool(exchange).exchange{ value: fromAmount }(
          curveData.i,
          curveData.j,
          fromAmount,
          1
        );
      } else {
        ICurvePool(exchange).exchange(curveData.i, curveData.j, fromAmount, 1);
      }
    }
  }
}

