      ? WETH
      : address(toToken);

    if (address(fromToken) == Utils.ethAddress()) {
      IWETH(WETH).deposit{ value: fromAmount }();
    }

    uint256 totalInParam;
    for (uint i = 0; i < data.swaps.length; ++i) {
      totalInParam = totalInParam.add(data.swaps[i].tokenInParam);
