 * 9- MStable
 * 10- CurveV2
 * The above are the indexes
 */
contract Adapter01 is
  IAdapter,
  NewUniswapV2,
  ZeroxV4,
  ZeroxV2,
  Curve,
  Balancer,
  UniswapV3,
  Aavee2,
