    } else if (data.opType == uint(OpType.swap)) {
      IMStable(exchange).swap(
        address(fromToken),
        address(toToken),
        fromAmount,
        1,
        address(this)
      );
    } else {
      revert("Invalid opType");
    }
  }
}

