    IZeroxV2(exchange).marketSellOrdersNoThrow(
      data.orders,
      fromAmount,
      data.signatures
    );

    if (address(toToken) == Utils.ethAddress()) {
      uint256 receivedAmount = Utils.tokenBalance(WETH, address(this));
      IWETH(WETH).withdraw(receivedAmount);
    }
  }
}

