  function swapOnZeroXv4(
    IERC20 fromToken,
    IERC20 toToken,
    uint256 fromAmount,
    address exchange,
    bytes calldata payload
  ) internal {
    if (address(fromToken) == Utils.ethAddress()) {
      IWETH(WETH).deposit{ value: fromAmount }();
    }

    _swapOn0xV4(fromToken, toToken, fromAmount, exchange, payload);
  }

  function buyOnZeroXv4(
    IERC20 fromToken,
    IERC20 toToken,
    uint256 fromAmount,
    address exchange,
    bytes calldata payload
  ) internal {
    if (address(fromToken) == Utils.ethAddress()) {
      IWETH(WETH).deposit{ value: fromAmount }();
    }

    _swapOn0xV4(fromToken, toToken, fromAmount, exchange, payload);

    if (address(fromToken) == Utils.ethAddress()) {
      uint256 remainingAmount = Utils.tokenBalance(WETH, address(this));
      if (remainingAmount > 0) {
        IWETH(WETH).withdraw(remainingAmount);
      }
    }
  }

  function _swapOn0xV4(
    IERC20 fromToken,
    IERC20 toToken,
    uint256 fromAmount,
    address exchange,
    bytes memory payload
  ) private {
    ZeroxV4Data memory data = abi.decode(payload, (ZeroxV4Data));

    address _fromToken = address(fromToken);
    address _toToken = address(toToken);
    require(
      _fromToken != _toToken,
      "fromToken should be different from toToken"
    );

    if (address(fromToken) == Utils.ethAddress()) {
      _fromToken = WETH;
    } else if (address(toToken) == Utils.ethAddress()) {
      _toToken = WETH;
    }

    require(
