pragma solidity 0.7.5;

contract OneInchPool {
  function swapOnOneInch(
    IERC20 fromToken,
    IERC20 toToken,
    uint256 fromAmount,
    address exchange
  ) internal {
    address _fromToken = address(fromToken) == Utils.ethAddress()
      ? address(0)
      : address(fromToken);
